begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a2580000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','dsr-unexecuted258@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code)values('a2580000-0000-4000-8000-000000000001','COMPLIANCE_MANAGER');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2580000-0000-4000-8000-000000000001','TEST DSR258','TEST DSR258','ACTIVE','a2580000-0000-4000-8000-000000000001');
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)select('d2580000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'b2580000-0000-4000-8000-000000000001',typ,repeat('a',64),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',now(),extensions.gen_random_uuid(),'a2580000-0000-4000-8000-000000000001'from unnest(array['OPPOSITION','CONSENT_WITHDRAWAL','OTHER','ERASURE'])with ordinality x(typ,i);
set local role authenticated;
select set_config('request.jwt.claim.sub','a2580000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2580000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.transition_data_subject_request('d2580000-0000-4000-8000-000000000001',1,'FULFILLED','TEST_REFERENCE_ONLY','TEST_REFERENCE_ONLY',extensions.gen_random_uuid())$$,'55000','PRIVACY_TYPED_RIGHT_EXECUTION_PROOF_REQUIRED','a reference cannot claim an executed objection');
select throws_ok($$select public.transition_data_subject_request('d2580000-0000-4000-8000-000000000002',1,'FULFILLED','TEST_REFERENCE_ONLY','TEST_REFERENCE_ONLY',extensions.gen_random_uuid())$$,'55000','PRIVACY_TYPED_RIGHT_EXECUTION_PROOF_REQUIRED','a reference cannot fabricate a withdrawn consent');
select throws_ok($$select public.transition_data_subject_request('d2580000-0000-4000-8000-000000000003',1,'FULFILLED','TEST_REFERENCE_ONLY','TEST_REFERENCE_ONLY',extensions.gen_random_uuid())$$,'55000','PRIVACY_TYPED_RIGHT_EXECUTION_PROOF_REQUIRED','an unspecified operation cannot become fulfilled without an actual typed effect');
select throws_ok($$select public.transition_data_subject_request('d2580000-0000-4000-8000-000000000004',1,'FULFILLED','TEST_REFERENCE_ONLY','TEST_REFERENCE_ONLY',extensions.gen_random_uuid())$$,'55000','PRIVACY_FULL_ERASURE_EVIDENCE_REQUIRED','the existing full erasure evidence gate remains closed');
reset role;
select is((select count(*)from public.data_subject_requests where organization_id='b2580000-0000-4000-8000-000000000001'and status='IN_REVIEW'),4::bigint,'all requests remain explicitly in review after the rejected false completions');
select is((select count(*)from public.consent_records where organization_id='b2580000-0000-4000-8000-000000000001'),0::bigint,'blocking a false completion never manufactures a consent record');
select is((select count(*)from public.event_outbox where organization_id='b2580000-0000-4000-8000-000000000001'and event_type='PrivacyDataSubjectRequestTransitionedV1'),0::bigint,'no fulfilled transition fact is emitted for an unexecuted right');
select*from finish();rollback;
